#define GEF_SF_NENTRIES  ((int)(sizeof(gef_sf_table)/sizeof(gef_sf_table[0])))

/* Returns pointer to GEFSFSpectrum for given ZA, or NULL if not tabulated. */
static const GEFSFSpectrum* find_gef_sf_spectrum(int za) {
   for (int i = 0; i < GEF_SF_NENTRIES; i++)
      if (gef_sf_table[i].ZA == za) return &gef_sf_table[i];
   return NULL;
}

/*
 * Sample a delayed neutron energy from the GEF tabulated spectrum
 * using inverse-CDF.  u is a uniform [0,1) variate.
 */
static double smpGEFSFEnergy(const GEFSFSpectrum* sp, double u) {
   double cdf = 0.0;
   for (int i = 0; i < GEF_SF_NBIN; i++) {
      cdf += sp->spectrum[i] * GEF_SF_BIN_WIDTH;
      if (u <= cdf)
         return GEF_SF_E_MIN + i * GEF_SF_BIN_WIDTH;
   }
   return GEF_SF_E_MIN + (GEF_SF_NBIN - 1) * GEF_SF_BIN_WIDTH;
}

